        if args.local_rank >= 0:
            env_local_rank = int(os.environ.get("LOCAL_RANK"))
            assert (
                env_local_rank == args.local_rank
            ), f"Mismatch in local rank setting, args.local_rank={args.local_rank} but env['LOCAL_RANK']={env_local_rank}."

